using System;using System.Reflection;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using Rootborn.Game.Localization;using Rootborn.UI.Modern;using Rootborn.UI.StudentLife;
namespace Rootborn.Tests.EditMode.UI{public sealed class CareerShortcutPresentationTests{
[TestCase("Interest","ko","관심사")][TestCase("Interest","en","Interests")][TestCase("Candidate","ko","진로")][TestCase("Candidate","en","Careers")]
public void CareerShortcutsUseApprovedSkinAndReadableLocalizedLabels(string kind,string language,string expected){string old=GameText.Language;var canvasObject=new GameObject("ShortcutCanvas",typeof(RectTransform),typeof(Canvas));var runnerObject=new GameObject("ShortcutRunner");try{GameText.Language=language;var installer=kind=="Interest"?typeof(CareerInterestRuntimeInstaller):typeof(CareerCandidateRuntimeInstaller);var type=installer.GetNestedType("Runner",BindingFlags.NonPublic);var runner=runnerObject.AddComponent(type);var method=type.GetMethod("EnsureOpenButton",BindingFlags.Instance|BindingFlags.NonPublic);var canvas=canvasObject.GetComponent<Canvas>();var args=kind=="Interest"?new object[]{canvas}:new object[]{canvas,null};method.Invoke(runner,args);method.Invoke(runner,args);var buttons=canvasObject.GetComponentsInChildren<Button>(true);Assert.That(buttons.Length,Is.EqualTo(1));var button=buttons[0];Assert.That(button.GetComponent<ModernUiTileImage>(),Is.Not.Null,"Shortcut must share the approved ComfyUI molding skin");Assert.That(button.GetComponent<RectTransform>().sizeDelta.y,Is.GreaterThanOrEqualTo(48));var label=button.transform.Find("Label").GetComponent<Text>();Assert.That(label.text,Is.EqualTo(expected));Assert.That(label.font,Is.SameAs(typeof(CareerInterestPanel).Assembly.GetType("Rootborn.UI.StudentLife.LifeUiFont").GetProperty("Shared",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static).GetValue(null)));Assert.That(label.raycastTarget,Is.False);}finally{GameText.Language=old;UnityEngine.Object.DestroyImmediate(runnerObject);UnityEngine.Object.DestroyImmediate(canvasObject);}}
}}

